'use strict';
// data/voice/boppy.js — boppy's baked clips (loaded after data/voice-clips.js). Merge from the Voice Baker; do not hand-edit.
VOICE_CLIPS.clips.boppy={"greet":[{"text":"Grace, Rose! Slow down! Why does everybody walk so fast?","mp3":"","model":"eleven_v4"},{"text":"Did I ever tell you I was a champion cross country runner? Sit down.","mp3":"","model":"eleven_v4"},{"text":"Tom! Good. I'm not feeling good. It's the stomach.","mp3":"","model":"eleven_v4"}],"praise":[{"text":"My stomach says no. My heart says one song. Just one. Slow.","mp3":"","model":"eleven_v4"},{"text":"Did I ever tell you I won a dance contest? 1970. Sit down. I mean, stand up.","mp3":"","model":"eleven_v4"}],"join":[{"text":"Need somebody to count heads? Count me in! Nobody gets past Boppy!","mp3":"","model":"eleven_v4"}],"basic":[{"text":"Cap swat! I've had this cap since Rikers!","mp3":"","model":"eleven_v4"},{"text":"Hah! Still got it. Ooh. My stomach.","mp3":"","model":"eleven_v4"}],"bigcatch":[{"text":"Big one! Biggest one! Somebody get the camera!","mp3":"","model":"eleven_v4"}],"cap_swat":[{"text":"Cap swat! I've had this cap since Rikers!","mp3":"","model":"eleven_v4"}],"cast":[{"text":"Set the hook! Ooh, too much twisting. My stomach!","mp3":"","model":"eleven_v4"}],"dc1":[{"text":"Shh! Keep it down, Tom, you're scaring the fish!","mp3":"","model":"eleven_v4"}],"dc2":[{"text":"Hand me the wrench. No, the OTHER wrench.","mp3":"","model":"eleven_v4"}],"dc3":[{"text":"That one's mild. Have another.","mp3":"","model":"eleven_v4"}],"dcff3":[{"text":"Where's the fire? Everybody walks too fast!","mp3":"","model":"eleven_v4"}],"everybody_waits":[{"text":"Everybody slow down. My family goes first!","mp3":"","model":"eleven_v4"}],"ff3":[{"text":"Even with my stomach? Yeah. Me too, Deedee.","mp3":"","model":"eleven_v4"}],"fish_ult":[{"text":"Told you the fish was THIS big! Stand back, kids!","mp3":"","model":"eleven_v4"}],"five_alarm_jar":[{"text":"Ghost pepper! Nobody stop me! Ohh, somebody stop me.","mp3":"","model":"eleven_v4"}],"ghost":[{"text":"Ghost pepper! Nobody stop me! Ohh, somebody stop me.","mp3":"","model":"eleven_v4"}],"gotaway":[{"text":"It was THIS big! I told you it was THIS big!","mp3":"","model":"eleven_v4"}],"grumble":[{"text":"I'm not feeling good. Something with the stomach. Nobody asked.","mp3":"","model":"eleven_v4"},{"text":"My stomach is acting up, and everybody walks too fast!","mp3":"","model":"eleven_v4"}],"headcount_again":[{"text":"Headcount, again. Nobody move while I count.","mp3":"","model":"eleven_v4"}],"hotpepper":[{"text":"Grew this one myself! Eat up, slimy!","mp3":"","model":"eleven_v4"}],"hurt":[{"text":"Agh! Right in the stomach! I wasn't feeling good BEFORE that!","mp3":"","model":"eleven_v4"},{"text":"Hey! All those years at Rikers and nobody hit me like that!","mp3":"","model":"eleven_v4"}],"ko":[{"text":"I need the recliner. Tell Deedee I was brave.","mp3":"","model":"eleven_v4"}],"lockdown":[{"text":"Lockdown! The deputy warden says nobody gets out!","mp3":"","model":"eleven_v4"}],"low":[{"text":"I'm not feeling good. Somebody get me a ginger ale.","mp3":"","model":"eleven_v4"}],"mild_for_company":[{"text":"Mild for company. I checked this time.","mp3":"","model":"eleven_v4"}],"nineteen_seventy":[{"text":"In nineteen seventy, before everybody walked so fast...","mp3":"","model":"eleven_v4"}],"patient_angler":[{"text":"Patient angler. The fish can wait for me.","mp3":"","model":"eleven_v4"}],"pepper_breath":[{"text":"I had a pepper at lunch. You're about to find out.","mp3":"","model":"eleven_v4"}],"pepper":[{"text":"I had a pepper at lunch. You're about to find out.","mp3":"","model":"eleven_v4"}],"recliner_reservation":[{"text":"Recliner reservation. I suppose you can have it.","mp3":"","model":"eleven_v4"}],"recliner":[{"text":"Recliner! Nobody sits in it! Not even you!","mp3":"","model":"eleven_v4"}],"roar":[{"text":"Nobody gets past me! NOBODY!","mp3":"","model":"eleven_v4"}],"seeds_of_trouble":[{"text":"Seeds of trouble. I grew these myself.","mp3":"","model":"eleven_v4"}],"tombo2":[{"text":"Lock it down, Tom! Nobody gets past us!","mp3":"","model":"eleven_v4"}],"tombo3":[{"text":"A tomato needs a cage, Tom. Like an inmate.","mp3":"","model":"eleven_v4"}],"tombo":[{"text":"Hold the net STILL. Why's it moving?","mp3":"","model":"eleven_v4"}],"trackstar":[{"text":"Did I ever tell you about 1970? Sit down. This takes a while.","mp3":"","model":"eleven_v4"}],"win":[{"text":"Champion! Just like my cross country days! Ooh, my stomach.","mp3":"","model":"eleven_v4"},{"text":"Everybody line up! Headcount! Good. Nobody's missing.","mp3":"","model":"eleven_v4"},{"text":"Who's the strongest grandpa? Correct.","mp3":"","model":"eleven_v4"}],"xc_ult":[{"text":"Nineteen seventy! Up the hills, and nobody caught me!","mp3":"","model":"eleven_v4"}]};
